import{_ as t,o as a,c as s,an as o}from"./chunks/framework.CS33E9Du.js";const g=JSON.parse('{"title":"Data sources","description":"","frontmatter":{},"headers":[],"relativePath":"config/data_sources.md","filePath":"config/data_sources.md","lastUpdated":null}'),r={name:"config/data_sources.md"};function i(n,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="Data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#Data-sources" aria-label="Permalink to &quot;Data sources {#Data-sources}&quot;">​</a></h1><p>This page covers where to obtain the raw meteorological input the preprocessor needs, how to authenticate against each source, and the recommended local layout under <code>~/data/AtmosTransport/met/</code>.</p><p>If you only want to run the model and don&#39;t care about the preprocessing pipeline, <strong>skip to <a href="/AtmosTransport.jl/v0.2/config/data_sources#The-quickstart-bundle">the quickstart bundle</a></strong> at the end — that&#39;s preprocessed binaries already, downloadable from a GitHub Release.</p><h2 id="ERA5-ECMWF-Reanalysis-5" tabindex="-1">ERA5 (ECMWF Reanalysis 5) <a class="header-anchor" href="#ERA5-ECMWF-Reanalysis-5" aria-label="Permalink to &quot;ERA5 (ECMWF Reanalysis 5) {#ERA5-ECMWF-Reanalysis-5}&quot;">​</a></h2><p>ERA5 is the primary spectral source for the LL / CS spectral preprocessing path. Authoritative source: the <a href="https://cds.climate.copernicus.eu/" target="_blank" rel="noreferrer">Copernicus Climate Data Store (CDS)</a>.</p><h3 id="What-you-need-per-day" tabindex="-1">What you need per day <a class="header-anchor" href="#What-you-need-per-day" aria-label="Permalink to &quot;What you need per day {#What-you-need-per-day}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">File</th><th style="text-align:right;">Variable</th><th style="text-align:right;">Format</th></tr></thead><tbody><tr><td style="text-align:right;"><code>era5_spectral_YYYYMMDD_lnsp.gb</code></td><td style="text-align:right;">log surface pressure (LNSP) spectral coefficients</td><td style="text-align:right;">GRIB</td></tr><tr><td style="text-align:right;"><code>era5_spectral_YYYYMMDD_vo_d.gb</code></td><td style="text-align:right;">vorticity + divergence (VO + D) spectral coefficients</td><td style="text-align:right;">GRIB</td></tr><tr><td style="text-align:right;"><code>era5_thermo_ml_YYYYMMDD.nc</code></td><td style="text-align:right;">model-level specific humidity (<code>q</code>), temperature, etc.</td><td style="text-align:right;">NetCDF</td></tr></tbody></table><p>The thermo file is mandatory for <code>mass_basis = &quot;dry&quot;</code> (the runtime default). All three files are model-level (137 levels, hybrid σ-p).</p><h3 id="Credentials" tabindex="-1">Credentials <a class="header-anchor" href="#Credentials" aria-label="Permalink to &quot;Credentials {#Credentials}&quot;">​</a></h3><p>Get a free CDS account, then drop your Personal Access Token (PAT) in <code>~/.cdsapirc</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>url: https://cds.climate.copernicus.eu/api</span></span>
<span class="line"><span>key: &lt;YOUR-PAT&gt;</span></span></code></pre></div><p>CDS migrated to single PAT-style keys in September 2024; the legacy <code>&lt;UID&gt;:&lt;API-KEY&gt;</code> format is no longer accepted. Get your PAT from your CDS account profile page once you&#39;re logged in. The <code>base_url</code> in <code>config/met_sources/era5.toml</code> matches this. Tools that read the CDS API will pick up the <code>~/.cdsapirc</code> file automatically.</p><h3 id="Datasets" tabindex="-1">Datasets <a class="header-anchor" href="#Datasets" aria-label="Permalink to &quot;Datasets {#Datasets}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">CDS dataset name</th><th style="text-align:right;">Use</th></tr></thead><tbody><tr><td style="text-align:right;"><code>reanalysis-era5-complete</code></td><td style="text-align:right;">Model-level spectral fields (VO, D, LNSP) — the AtmosTransport spectral preprocessor input</td></tr><tr><td style="text-align:right;"><code>reanalysis-era5-single-levels</code></td><td style="text-align:right;">Surface fields (PS, 2T, 10U, 10V, …)</td></tr><tr><td style="text-align:right;"><code>reanalysis-era5-pressure-levels</code></td><td style="text-align:right;">Pressure-level diagnostics (not used by the preprocessor)</td></tr></tbody></table><p>A reference download script lives outside the repository (the historical practice is per-user <code>cdsapi</code> calls); see <code>config/met_sources/era5.toml</code> for the canonical descriptor.</p><h3 id="Recommended-local-layout" tabindex="-1">Recommended local layout <a class="header-anchor" href="#Recommended-local-layout" aria-label="Permalink to &quot;Recommended local layout {#Recommended-local-layout}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/data/AtmosTransport/met/era5/</span></span>
<span class="line"><span>└── 0.5x0.5/</span></span>
<span class="line"><span>    ├── spectral_hourly/                    # CDS reanalysis-era5-complete output</span></span>
<span class="line"><span>    │   ├── era5_spectral_20211201_lnsp.gb</span></span>
<span class="line"><span>    │   ├── era5_spectral_20211201_vo_d.gb</span></span>
<span class="line"><span>    │   └── …</span></span>
<span class="line"><span>    └── physics/</span></span>
<span class="line"><span>        └── era5_thermo_ml_20211201.nc      # CDS reanalysis-era5-complete with q</span></span></code></pre></div><p>The <code>spectral_dir</code> and <code>thermo_dir</code> keys in <a href="/AtmosTransport.jl/v0.2/config/toml_schema#TOML-schema">TOML schema</a> point at these.</p><h2 id="GEOS-IT-NASA-GMAO-Integrated-Tropospheric" tabindex="-1">GEOS-IT (NASA GMAO Integrated Tropospheric) <a class="header-anchor" href="#GEOS-IT-NASA-GMAO-Integrated-Tropospheric" aria-label="Permalink to &quot;GEOS-IT (NASA GMAO Integrated Tropospheric) {#GEOS-IT-NASA-GMAO-Integrated-Tropospheric}&quot;">​</a></h2><p>GEOS-IT is the primary native cubed-sphere source. C180 (~50 km) is the production/debug resolution. GEOS-FP native C720 hourly CTM files are wired through the same source contract, with optional 0.25° surface/convection fallback files attached into the preprocessed binary.</p><h3 id="Per-day-file-set" tabindex="-1">Per-day file set <a class="header-anchor" href="#Per-day-file-set" aria-label="Permalink to &quot;Per-day file set {#Per-day-file-set}&quot;">​</a></h3><p>For each <code>YYYYMMDD</code>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">File</th><th style="text-align:right;">Cadence</th><th style="text-align:right;">Variables</th></tr></thead><tbody><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.CTM_A1.C180.nc</code></td><td style="text-align:right;">hourly (window-averaged)</td><td style="text-align:right;"><code>MFXC</code>, <code>MFYC</code>, <code>DELP</code></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.CTM_I1.C180.nc</code></td><td style="text-align:right;">hourly (instantaneous)</td><td style="text-align:right;"><code>PS</code>, <code>QV</code></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.A1.C180.nc</code></td><td style="text-align:right;">hourly</td><td style="text-align:right;"><code>PBLH</code>, <code>USTAR</code>, <code>HFLUX</code>, <code>T2M</code> <em>(only with <code>include_surface</code>)</em></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.A3mstE.C180.nc</code></td><td style="text-align:right;">3-hourly</td><td style="text-align:right;"><code>CMFMC</code> <em>(only with <code>include_convection</code>)</em></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.A3dyn.C180.nc</code></td><td style="text-align:right;">3-hourly</td><td style="text-align:right;"><code>DTRAIN</code> <em>(only with <code>include_convection</code>)</em>; <code>U</code>, <code>V</code> <em>(with <code>include_vdiff_fields</code>)</em></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.I3.C180.nc</code></td><td style="text-align:right;">3-hourly</td><td style="text-align:right;"><code>T</code> <em>(only with <code>include_vdiff_fields</code>)</em></td></tr></tbody></table><p>The GCHP Holtslag-Boville VDIFF data contract additionally requires <code>include_vdiff_fields = true</code> in the preprocessing TOML and the <code>config/downloads/geosit_c180_gchp_vdiff.toml</code> download recipe.</p><p>The preprocessor needs <strong>next-day hour 0</strong> for the last window&#39;s forward-flux endpoint; download <code>[start, end+1]</code> for production runs.</p><h3 id="Access" tabindex="-1">Access <a class="header-anchor" href="#Access" aria-label="Permalink to &quot;Access {#Access}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Source</th><th style="text-align:right;">URL pattern</th><th style="text-align:right;">Auth</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>AWS S3 (primary)</strong> — <code>s3://geos-chem/GEOS_C180/GEOS_IT/...</code></td><td style="text-align:right;">public bucket; requester-pays NOT required</td><td style="text-align:right;">none — use <code>aws s3 cp --no-sign-request</code></td></tr><tr><td style="text-align:right;">WashU HTTP archive (fallback)</td><td style="text-align:right;"><code>http://geoschemdata.wustl.edu/ExtData/GEOS_C180/GEOS_IT/...</code></td><td style="text-align:right;">none</td></tr></tbody></table><p>The canonical descriptor is <code>config/met_sources/geosit.toml</code> (line 50-60), including the bucket name and the WashU base URL.</p><h3 id="Recommended-local-layout-2" tabindex="-1">Recommended local layout <a class="header-anchor" href="#Recommended-local-layout-2" aria-label="Permalink to &quot;Recommended local layout {#Recommended-local-layout-2}&quot;">​</a></h3><p>The downloader&#39;s canonical layout puts each day&#39;s collections under a per-day subdirectory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/data/AtmosTransport/met/geosit/</span></span>
<span class="line"><span>└── C180/</span></span>
<span class="line"><span>    └── daily/</span></span>
<span class="line"><span>        └── raw/</span></span>
<span class="line"><span>            └── 20211201/</span></span>
<span class="line"><span>                ├── GEOSIT.20211201.CTM_A1.C180.nc</span></span>
<span class="line"><span>                ├── GEOSIT.20211201.CTM_I1.C180.nc</span></span>
<span class="line"><span>                ├── GEOSIT.20211201.A3mstE.C180.nc       # if convection</span></span>
<span class="line"><span>                ├── GEOSIT.20211201.A3dyn.C180.nc        # if convection or VDIFF</span></span>
<span class="line"><span>                └── GEOSIT.20211201.I3.C180.nc           # if GCHP VDIFF</span></span></code></pre></div><p>The <code>[source].root_dir</code> key in the GEOS preprocessing TOML points at the parent directory containing the <code>YYYYMMDD/</code> per-day folders (<code>~/data/AtmosTransport/met/geosit/C180/daily/raw</code> in this layout). The preprocessor&#39;s file resolver also accepts a flat directory of all NetCDFs (no per-day subdir) — that&#39;s the <code>raw_catrine</code> layout the project&#39;s own configs use historically.</p><h2 id="GEOS-FP,-MERRA-2-status" tabindex="-1">GEOS-FP, MERRA-2 (status) <a class="header-anchor" href="#GEOS-FP,-MERRA-2-status" aria-label="Permalink to &quot;GEOS-FP, MERRA-2 (status) {#GEOS-FP,-MERRA-2-status}&quot;">​</a></h2><p><strong>GEOS-FP (C720).</strong> The active descriptor is native cubed-sphere:</p><ul><li><p><code>config/met_sources/geosfp.toml</code> — the <strong>native C720 hourly CTM</strong> product (<code>GEOS.fp.asm.tavg_1hr_ctm_c0720_v72.*.nc4</code>).</p></li><li><p><code>config/downloads/geosfp_c720.toml</code> — the <strong>native C720</strong> cubed-sphere download descriptor; the <strong><code>src/Downloads/sources/geosfp.jl</code></strong> downloader pulls from the WashU HTTP archive (NOT the GEOS-IT-style AWS S3 path) into a local directory.</p></li></ul><p><code>GEOSSettings{:geosfp}</code> opens 24 hourly native CTM files plus the next-day 00Z endpoint. The WashU archive names the hourly averaged files with <code>HH30</code> timestamps; the resolver also accepts legacy <code>HH00</code> fixtures. When <code>[source] include_surface = true</code> or <code>include_convection = true</code>, set <code>[source] physics_dir</code> to a directory containing <code>GEOSFP.YYYYMMDD.{A1,A3mstE,A3dyn}.025x03125.nc</code> files (or pre-regridded CS equivalents) and the preprocessor embeds <code>PBLH</code>, <code>USTAR</code>, <code>HFLUX</code>, <code>T2M</code>, <code>CMFMC</code>, and <code>DTRAIN</code> in the transport binary.</p><p><strong>MERRA-2.</strong> Descriptor stub at <code>config/met_sources/merra2.toml</code>, but MERRA-2 is <strong>not</strong> an <code>AbstractGEOSSettings</code> preprocessing path — it has no native MFXC/MFYC, so the GEOS shortcut doesn&#39;t apply. A MERRA-2 preprocessing path would need its own settings type that derives mass fluxes from U/V/DELP at LL cell centers (closer in shape to the spectral path); not implemented today. NASA Earthdata Login auth would be required for actual data access.</p><h2 id="The-quickstart-bundle" tabindex="-1">The quickstart bundle <a class="header-anchor" href="#The-quickstart-bundle" aria-label="Permalink to &quot;The quickstart bundle {#The-quickstart-bundle}&quot;">​</a></h2><p>If you don&#39;t want to manage raw met data — for a smoke test, a tutorial, or a short benchmark — there&#39;s a <strong>preprocessed bundle</strong> on the <a href="https://github.com/RemoteSensingTools/AtmosTransport.jl/releases/tag/data-quickstart-v2" target="_blank" rel="noreferrer"><code>data-quickstart-v2</code> GitHub Release</a>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Tarball</th><th style="text-align:right;">Contents</th></tr></thead><tbody><tr><td style="text-align:right;"><code>quickstart_ll_dec2021_v2.tar.gz</code> (~1.0 GB)</td><td style="text-align:right;">LL 72x37 + LL 144x73 transport binaries, F32, Dec 1-3 2021</td></tr><tr><td style="text-align:right;"><code>quickstart_cs_dec2021_v2.tar.gz</code> (~1.9 GB)</td><td style="text-align:right;">CS C24 + CS C90 transport binaries, F32, Dec 1-3 2021</td></tr></tbody></table><p>Both built from raw ERA5 spectral via the preprocessor described in <a href="/AtmosTransport.jl/v0.2/preprocessing/spectral_era5#ERA5-spectral-path">ERA5 spectral path</a>. Use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/download_quickstart_data.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ll</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # newcomer path</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/download_quickstart_data.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/download_quickstart_data.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # both</span></span></code></pre></div><p>The quickstart downloader and run configs use <code>$ATMOSTRANSPORT_DATA_ROOT_quickstart</code>, defaulting to <code>~/data/AtmosTransport_quickstart</code>. Set it before downloading if the bundle should live somewhere else:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ATMOSTRANSPORT_DATA_ROOT_quickstart</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/scratch/$USER/AtmosTransport_quickstart</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/download_quickstart_data.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ll</span></span></code></pre></div><p>See <a href="/AtmosTransport.jl/v0.2/getting_started/quickstart#Quickstart-with-example-data">Quickstart with example data</a> for the runnable walkthrough.</p><h2 id="A-note-on-disk-space" tabindex="-1">A note on disk space <a class="header-anchor" href="#A-note-on-disk-space" aria-label="Permalink to &quot;A note on disk space {#A-note-on-disk-space}&quot;">​</a></h2><p>For reference, a 30-day production preprocessing job needs:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Source × target</th><th style="text-align:right;">Raw input</th><th style="text-align:right;">Binary output (F32)</th></tr></thead><tbody><tr><td style="text-align:right;">ERA5 spectral → LL 720×361 (full ERA5 res)</td><td style="text-align:right;">~6 GB / day raw GRIB+NetCDF</td><td style="text-align:right;">~5 GB / day binary</td></tr><tr><td style="text-align:right;">ERA5 spectral → CS C90</td><td style="text-align:right;">same raw</td><td style="text-align:right;">~700 MB / day binary</td></tr><tr><td style="text-align:right;">GEOS-IT C180 → CS C180 (passthrough)</td><td style="text-align:right;">~3 GB / day raw NetCDF</td><td style="text-align:right;">~3 GB / day binary</td></tr></tbody></table><p>Plan storage accordingly; production run datasets are tens to hundreds of GB.</p><h2 id="Where-to-read-next" tabindex="-1">Where to read next <a class="header-anchor" href="#Where-to-read-next" aria-label="Permalink to &quot;Where to read next {#Where-to-read-next}&quot;">​</a></h2><ul><li><p><a href="/AtmosTransport.jl/v0.2/getting_started/quickstart#Quickstart-with-example-data">Quickstart with example data</a> — runnable bundle walkthrough.</p></li><li><p><a href="/AtmosTransport.jl/v0.2/config/toml_schema#TOML-schema">TOML schema</a> — <code>[input]</code> / <code>[source]</code> / <code>[grid]</code> reference.</p></li><li><p><a href="/AtmosTransport.jl/v0.2/preprocessing/overview#Preprocessing-overview">Preprocessing overview</a> — the unified <code>process_day</code> dispatch.</p></li></ul>`,51)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
